package com.apple.spark.operator;

import static com.apple.spark.core.SparkConstants.DRIVER_CORE_DEFAULT;
import static com.apple.spark.core.SparkConstants.DRIVER_MEM_DEFAULT;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;
import io.swagger.v3.oas.annotations.Hidden;

@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
public class DriverSpec extends SparkPodSpec {

    @Hidden
    private String podName;

    @Hidden
    private String kubernetesMaster;

    public DriverSpec() {
        this.setCores(DRIVER_CORE_DEFAULT);
        this.setMemory(DRIVER_MEM_DEFAULT);
    }

    public void copyFrom(DriverSpec another) {
        super.copyFrom(another);
        this.podName = another.podName;
        this.kubernetesMaster = another.kubernetesMaster;
    }

    public String getPodName() {
        return podName;
    }

    public void setPodName(String podName) {
        this.podName = podName;
    }

    public String getKubernetesMaster() {
        return kubernetesMaster;
    }

    public void setKubernetesMaster(String kubernetesMaster) {
        this.kubernetesMaster = kubernetesMaster;
    }
}

